record.field:
from datetime import date, timedelta
today = date.today()
cutoff_30 = today - timedelta(days=30)
cutoff_7 = today - timedelta(days=7)

low_criteria = env['naac.criterion'].search([('readiness_score', '<', 50.0)])

old_evidence = env['naac.evidence'].search([
    ('is_verified', '=', False),
    ('upload_date', '<', cutoff_30),
])

stale_activities = env['naac.department.activity'].search([
    ('state', '=', 'submitted'),
    ('write_date', '<', cutoff_7),
])

if low_criteria or old_evidence or stale_activities:
    msg_lines = []
    if low_criteria:
        msg_lines.append('%d NAAC criteria below 50%% readiness.' % len(low_criteria))
    if old_evidence:
        msg_lines.append('%d evidence documents pending verification (30+ days).' % len(old_evidence))
    if stale_activities:
        msg_lines.append('%d activities awaiting verification (7+ days).' % len(stale_activities))
    body_text = '\n'.join(msg_lines)
    body_html = '<p>' + body_text.replace('\n', '<br/>') + '</p>'
    admin_users = env['res.users'].search([('groups_id.category_id.name', '=', 'University Management')])
    for user in admin_users:
        if user.email:
            env['mail.mail'].sudo().create({
                'subject': 'NAAC Compliance Alert - Action Required',
                'body_html': body_html,
                'email_to': user.email,
            }).send()
